//! Gateway-managed Worker inventory, approval persistence, and lease lifecycle.
//!
//! These are real processes: the Gateway, a General Worker, and the CLI/SDK
//! consumers. Control tokens are generated by the Gateway and never printed by
//! inventory, discovery, audit, or error output.

use serde_json::{json, Value};
use std::io::{BufRead, BufReader};
use std::net::TcpListener;
use std::path::{Path, PathBuf};
use std::process::{Child, ChildStdout, Command, Stdio};
use std::thread::sleep;
use std::time::{Duration, Instant};

const ADMIN_TOKEN: &str = "t44-admin-token";
const CALLER_TOKEN: &str = "t44-caller-token";
const DELEGATION_SECRET: &str = "t44-shared-delegation-secret";

fn binary(name: &str) -> PathBuf {
    if let Ok(path) = std::env::var(format!("CARGO_BIN_EXE_{name}")) {
        return PathBuf::from(path);
    }
    let current = std::env::current_exe().expect("test executable path");
    let mut directory = current.parent();
    while let Some(candidate_directory) = directory {
        let candidate = candidate_directory.join(name);
        if candidate.is_file() {
            return candidate;
        }
        directory = candidate_directory.parent();
    }
    panic!("{name} is missing; build workspace binaries before running cross-process tests");
}

fn client() -> reqwest::blocking::Client {
    reqwest::blocking::Client::new()
}

fn free_port() -> u16 {
    let listener = TcpListener::bind("127.0.0.1:0").expect("ephemeral port");
    listener.local_addr().expect("ephemeral address").port()
}

fn worker_config(data: &Path, token: &str, gateway: &str, advertise: &str) -> PathBuf {
    let assets = data.join("assets");
    let agents = assets.join("agents");
    let prompts = assets.join("prompts");
    std::fs::create_dir_all(&agents).expect("agent directory");
    std::fs::create_dir_all(&prompts).expect("prompt directory");
    std::fs::write(
        prompts.join("general.md"),
        "You are the Goldenbee General Worker. Answer usefully and concisely.",
    )
    .expect("general prompt");
    std::fs::write(
        prompts.join("echo.md"),
        "Repeat the user's message. Keep it short.",
    )
    .expect("echo prompt");
    std::fs::write(
        agents.join("general.toml"),
        "name = \"general\"\ndescription = \"General Worker\"\nmodel = \"deterministic\"\nprompt = \"general\"\ntools = [\"exec_command\"]\n",
    )
    .expect("general agent");
    std::fs::write(
        agents.join("echo.toml"),
        "name = \"echo\"\ndescription = \"Echo Worker\"\nmodel = \"deterministic\"\nprompt = \"echo\"\n",
    )
    .expect("echo agent");
    let config = format!(
        "instance = \"gateway-admin-fixture\"\nnamespace = \"local\"\ndefault_agent = \"general\"\ntoken = \"worker-local-token\"\ntoken_scopes = [\"*\"]\n\n[paths]\nagents = \"assets/agents\"\nprompts = \"assets/prompts\"\n\n[storage]\ndirectory = \"{}\"\n\n[gateway]\nurl = \"{gateway}\"\ncontrol_token = \"{token}\"\nrenew_interval_ms = 200\nadvertise_url = \"{advertise}\"\n",
        data.display()
    );
    let path = data.join("worker.toml");
    std::fs::write(&path, config).expect("worker config");
    path
}

struct Worker {
    child: Child,
    _data: tempfile::TempDir,
    config: PathBuf,
    base: String,
    instance: String,
    incarnation: String,
}

impl Drop for Worker {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

fn spawn_worker_process(config: &Path, address: &str) -> (Child, String) {
    let mut child = Command::new(binary("general"))
        .args([
            "serve",
            "--config",
            config.to_str().expect("config path"),
            "--addr",
            address,
        ])
        .env("GOLDENBEE_DELEGATION_SECRET", DELEGATION_SECRET)
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
        .expect("general worker starts");
    let stdout = child.stdout.take().expect("worker stdout is piped");
    let mut line = String::new();
    BufReader::new(stdout)
        .read_line(&mut line)
        .expect("worker announces its listener");
    let base = line
        .split("listening on ")
        .nth(1)
        .unwrap_or_else(|| panic!("worker address announcement: {line}"))
        .trim()
        .to_string();
    (child, base)
}

fn wait_health(base: &str) -> Value {
    let deadline = Instant::now() + Duration::from_secs(15);
    loop {
        if let Ok(response) = client().get(format!("{base}/v1/health")).send() {
            if let Ok(value) = response.json::<Value>() {
                return value;
            }
        }
        assert!(
            Instant::now() < deadline,
            "worker health at {base} did not respond"
        );
        sleep(Duration::from_millis(20));
    }
}

fn start_worker(data: tempfile::TempDir, token: &str, gateway: &str, address: &str) -> Worker {
    let base = format!("http://{address}");
    let config = worker_config(data.path(), token, gateway, &base);
    let (child, base) = spawn_worker_process(&config, address);
    let health = wait_health(&base);
    Worker {
        child,
        _data: data,
        config,
        base,
        instance: health["instance"].as_str().expect("instance").to_string(),
        incarnation: health["incarnation"]
            .as_str()
            .expect("incarnation")
            .to_string(),
    }
}

impl Worker {
    fn restart(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
        let address = self
            .base
            .strip_prefix("http://")
            .unwrap_or(&self.base)
            .to_string();
        let (child, base) = spawn_worker_process(&self.config, &address);
        let health = wait_health(&base);
        self.child = child;
        self.base = base;
        self.instance = health["instance"].as_str().expect("instance").to_string();
        self.incarnation = health["incarnation"]
            .as_str()
            .expect("incarnation")
            .to_string();
    }
}

struct Gateway {
    child: Child,
    _stdout: BufReader<ChildStdout>,
    config: PathBuf,
    _directory: tempfile::TempDir,
    registry: PathBuf,
    address: String,
    base: String,
}

impl Drop for Gateway {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

fn spawn_gateway(config: &Path, address: &str) -> (Child, BufReader<ChildStdout>, String) {
    let mut child = Command::new(binary("gb-gateway"))
        .args([
            "serve",
            "--addr",
            address,
            "--config",
            config.to_str().expect("configuration path"),
        ])
        .env("GOLDENBEE_DELEGATION_SECRET", DELEGATION_SECRET)
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
        .expect("gateway starts");
    let stdout = child.stdout.take().expect("gateway stdout is piped");
    let mut reader = BufReader::new(stdout);
    let mut line = String::new();
    reader
        .read_line(&mut line)
        .expect("gateway announces its listener");
    let base = line
        .split("listening on ")
        .nth(1)
        .unwrap_or_else(|| panic!("gateway address announcement: {line}"))
        .trim()
        .to_string();
    (child, reader, base)
}

impl Gateway {
    fn start() -> Self {
        let directory = tempfile::tempdir().expect("gateway directory");
        let config = directory.path().join("gateway.json");
        let registry = directory.path().join("registry.json");
        let document = json!({
            "listen": "127.0.0.1:0",
            "data_dir": directory.path().join("state"),
            "registry": registry,
            "lease_ttl_ms": 60000,
            "callers": [
                {
                    "token": ADMIN_TOKEN,
                    "id": "admin-1",
                    "namespace": "local",
                    "scopes": ["admin", "task:submit", "task:read", "task:cancel"]
                },
                {
                    "token": CALLER_TOKEN,
                    "id": "caller-1",
                    "namespace": "local",
                    "scopes": ["task:submit", "task:read", "task:cancel"]
                }
            ],
            "workers": []
        });
        std::fs::write(&config, serde_json::to_vec(&document).expect("config JSON"))
            .expect("gateway configuration");
        let address = format!("127.0.0.1:{}", free_port());
        let (child, reader, base) = spawn_gateway(&config, &address);
        Gateway {
            child,
            _stdout: reader,
            config,
            _directory: directory,
            registry,
            address,
            base,
        }
    }

    fn restart(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
        let (child, reader, base) = spawn_gateway(&self.config, &self.address);
        self.child = child;
        self._stdout = reader;
        self.base = base;
    }

    fn request(
        &self,
        method: reqwest::Method,
        path: &str,
        token: &str,
    ) -> reqwest::blocking::RequestBuilder {
        client()
            .request(method, format!("{}{path}", self.base))
            .bearer_auth(token)
    }

    fn add(&self, body: Value) -> reqwest::blocking::Response {
        self.request(reqwest::Method::POST, "/v1/admin/workers", ADMIN_TOKEN)
            .json(&body)
            .send()
            .expect("admin add responds")
    }

    fn update(&self, id: &str, body: Value) -> reqwest::blocking::Response {
        self.request(
            reqwest::Method::PATCH,
            &format!("/v1/admin/workers/{id}"),
            ADMIN_TOKEN,
        )
        .json(&body)
        .send()
        .expect("admin update responds")
    }

    fn action(&self, id: &str, action: &str) -> reqwest::blocking::Response {
        self.request(
            reqwest::Method::POST,
            &format!("/v1/admin/workers/{id}/{action}"),
            ADMIN_TOKEN,
        )
        .send()
        .expect("admin action responds")
    }

    fn remove(&self, id: &str) -> reqwest::blocking::Response {
        self.request(
            reqwest::Method::DELETE,
            &format!("/v1/admin/workers/{id}"),
            ADMIN_TOKEN,
        )
        .send()
        .expect("admin remove responds")
    }

    fn worker(&self, id: &str) -> Value {
        let response = self
            .request(
                reqwest::Method::GET,
                &format!("/v1/admin/workers/{id}"),
                ADMIN_TOKEN,
            )
            .send()
            .expect("admin get responds");
        assert!(response.status().is_success(), "admin get failed");
        response.json().expect("admin summary is JSON")
    }

    fn wait_worker(&self, id: &str, predicate: impl Fn(&Value) -> bool) -> Value {
        let deadline = Instant::now() + Duration::from_secs(25);
        let mut last = Value::Null;
        loop {
            let response = self
                .request(
                    reqwest::Method::GET,
                    &format!("/v1/admin/workers/{id}"),
                    ADMIN_TOKEN,
                )
                .send();
            if let Ok(response) = response {
                if response.status().is_success() {
                    if let Ok(value) = response.json::<Value>() {
                        if predicate(&value) {
                            return value;
                        }
                        last = value;
                    }
                }
            }
            assert!(
                Instant::now() < deadline,
                "worker '{id}' did not reach the expected state; last={last}"
            );
            sleep(Duration::from_millis(50));
        }
    }

    fn discover(&self, token: &str) -> Vec<Value> {
        let response = self
            .request(reqwest::Method::GET, "/v1/workers", token)
            .send()
            .expect("discovery responds");
        assert!(response.status().is_success(), "discovery failed");
        response.json().expect("discovery is JSON")
    }

    fn submit(&self, key: &str) -> reqwest::blocking::Response {
        self.request(reqwest::Method::POST, "/v1/tasks", CALLER_TOKEN)
            .json(&json!({
                "worker": "worker-live",
                "agent": "general",
                "session_id": format!("t44-{key}"),
                "input": "gateway managed worker lifecycle",
                "idempotency_key": key
            }))
            .send()
            .expect("submit responds")
    }

    fn wait_task(&self, id: &str) -> Value {
        let deadline = Instant::now() + Duration::from_secs(30);
        loop {
            let response = self
                .request(
                    reqwest::Method::GET,
                    &format!("/v1/tasks/{id}"),
                    CALLER_TOKEN,
                )
                .send()
                .expect("task responds");
            if response.status().is_success() {
                let projection: Value = response.json().expect("task is JSON");
                if matches!(
                    projection["task"]["state"].as_str(),
                    Some("succeeded" | "failed" | "cancelled" | "unknown")
                ) {
                    return projection;
                }
            }
            assert!(Instant::now() < deadline, "task {id} did not finish");
            sleep(Duration::from_millis(20));
        }
    }

    fn audit(&self, token: &str) -> Vec<Value> {
        let response = self
            .request(reqwest::Method::GET, "/v1/admin/workers/audit", token)
            .send()
            .expect("audit responds");
        assert!(response.status().is_success(), "audit failed");
        response.json().expect("audit is JSON")
    }
}

fn ids(workers: &[Value]) -> Vec<String> {
    workers
        .iter()
        .filter_map(|worker| worker["id"].as_str().map(str::to_string))
        .collect()
}

fn text(response: reqwest::blocking::Response) -> Value {
    response.json().expect("response is JSON")
}

#[test]
fn admin_manages_worker_inventory_registration_and_task_history() {
    let mut gateway = Gateway::start();
    let port = free_port();
    let endpoint = format!("http://127.0.0.1:{port}");

    let added = gateway.add(json!({
        "id": "worker-live",
        "endpoint": endpoint,
        "preflight": false,
        "idempotency_key": "add-worker-live"
    }));
    assert_eq!(added.status().as_u16(), 200);
    let added = text(added);
    let token = added["control_token"]
        .as_str()
        .expect("generated control token")
        .to_string();
    assert!(token.starts_with("gwb_"));
    assert_eq!(added["worker"]["status"], "approved");
    assert_eq!(added["worker"]["control_token_set"], true);
    assert_eq!(added["worker"]["revision"], 1);

    let retry = gateway.add(json!({
        "id": "worker-live",
        "endpoint": endpoint,
        "preflight": false,
        "idempotency_key": "add-worker-live"
    }));
    assert_eq!(retry.status().as_u16(), 200);
    let retry = text(retry);
    assert!(retry.get("control_token").is_none(), "token is one-time");
    assert_eq!(retry["worker"]["revision"], 1);

    let conflict = gateway.add(json!({
        "id": "worker-live",
        "endpoint": "http://127.0.0.1:1",
        "preflight": false,
        "idempotency_key": "add-worker-live"
    }));
    assert_eq!(conflict.status().as_u16(), 409);
    assert_eq!(text(conflict)["code"], "worker.idempotency_conflict");

    let mut worker = start_worker(
        tempfile::tempdir().expect("worker data"),
        &token,
        &gateway.base,
        &format!("127.0.0.1:{port}"),
    );
    let registered = gateway.wait_worker("worker-live", |worker| {
        worker["status"] == "registered" && worker["reachable"] == true
    });
    assert_eq!(registered["instance"], worker.instance);
    assert_eq!(registered["incarnation"], worker.incarnation);
    assert_eq!(registered["control_token_set"], true);

    let discovered = gateway.discover(CALLER_TOKEN);
    assert_eq!(ids(&discovered), vec!["worker-live"]);
    assert!(!serde_json::to_string(&discovered)
        .expect("discovery JSON")
        .contains(&token));

    let submitted = gateway.submit("t44-admin-task");
    assert_eq!(submitted.status().as_u16(), 200);
    let submitted = text(submitted);
    let task_id = submitted["task_id"].as_str().expect("task id").to_string();
    let completed = gateway.wait_task(&task_id);
    assert_eq!(completed["task"]["state"], "succeeded");
    let output = completed["task"]["output"].clone();

    let disabled = gateway.action("worker-live", "disable");
    assert_eq!(disabled.status().as_u16(), 200);
    let disabled = text(disabled);
    assert_eq!(disabled["status"], "disabled");
    assert_eq!(disabled["reachable"], false);

    let denied_register = client()
        .post(format!("{}/v1/workers/register", gateway.base))
        .bearer_auth(&token)
        .json(&json!({
            "endpoint": endpoint,
            "incarnation": worker.incarnation,
            "capacity": {"active": 0, "limit": 4, "queued": 0, "queue_limit": 8}
        }))
        .send()
        .expect("registration responds");
    assert_eq!(denied_register.status().as_u16(), 409);
    assert_eq!(text(denied_register)["code"], "worker.disabled");
    assert!(gateway.discover(CALLER_TOKEN).is_empty());
    let blocked = gateway.submit("t44-disabled-submit");
    assert!(!blocked.status().is_success());

    let preserved = gateway.wait_task(&task_id);
    assert_eq!(preserved["task"]["state"], "succeeded");
    assert_eq!(preserved["task"]["output"], output);

    let enabled = gateway.action("worker-live", "enable");
    assert_eq!(enabled.status().as_u16(), 200);
    assert_eq!(text(enabled)["status"], "unreachable");
    let reconnected = gateway.wait_worker("worker-live", |worker| {
        worker["reachable"] == true && worker["status"] == "registered"
    });
    let revision = reconnected["revision"].as_u64().expect("revision");
    assert_eq!(ids(&gateway.discover(CALLER_TOKEN)), vec!["worker-live"]);

    let moved = gateway.update(
        "worker-live",
        json!({"revision": revision, "endpoint": "http://127.0.0.1:1"}),
    );
    assert_eq!(moved.status().as_u16(), 409);
    assert_eq!(text(moved)["code"], "worker.endpoint_in_use");

    let narrowed = gateway.update(
        "worker-live",
        json!({"revision": revision, "capabilities": ["general"]}),
    );
    assert_eq!(narrowed.status().as_u16(), 200);
    let narrowed = text(narrowed);
    let revision = narrowed["revision"].as_u64().expect("revision");
    let expanded = gateway.update(
        "worker-live",
        json!({"revision": revision, "capabilities": ["general", "echo"]}),
    );
    assert_eq!(
        expanded.status().as_u16(),
        200,
        "{}",
        expanded.text().unwrap()
    );
    let expanded = text(expanded);
    assert_eq!(
        expanded["approved_capabilities"],
        json!(["general", "echo"])
    );
    let revision = expanded["revision"].as_u64().expect("revision");

    let first = gateway.update(
        "worker-live",
        json!({
            "revision": revision,
            "package": "general",
            "idempotency_key": "update-lost-ack"
        }),
    );
    assert_eq!(first.status().as_u16(), 200);
    let first = text(first);
    let committed = first["revision"].as_u64().expect("revision");
    let replay = gateway.update(
        "worker-live",
        json!({
            "revision": revision,
            "package": "general",
            "idempotency_key": "update-lost-ack"
        }),
    );
    assert_eq!(replay.status().as_u16(), 200);
    assert_eq!(text(replay)["revision"], committed);
    let stale = gateway.update(
        "worker-live",
        json!({
            "revision": revision,
            "package": "general",
            "idempotency_key": "different-update"
        }),
    );
    assert_eq!(stale.status().as_u16(), 409);
    assert_eq!(text(stale)["code"], "worker.revision_conflict");

    let mismatched = gateway.add(json!({
        "id": "worker-mismatch",
        "endpoint": endpoint,
        "instance": "not-the-live-instance",
        "control_token": "mismatch-control-token",
        "preflight": false,
        "idempotency_key": "add-worker-mismatch"
    }));
    assert_eq!(mismatched.status().as_u16(), 200);
    let probe = gateway.action("worker-mismatch", "probe");
    assert_eq!(probe.status().as_u16(), 403);
    assert_eq!(text(probe)["code"], "worker.instance_mismatch");
    let mismatch = gateway.worker("worker-mismatch");
    assert_eq!(mismatch["reachable"], false);
    assert_eq!(mismatch["status"], "unreachable");

    let duplicate = gateway.add(json!({
        "id": "worker-duplicate",
        "endpoint": endpoint,
        "control_token": "duplicate-control-token",
        "preflight": false,
        "idempotency_key": "add-worker-duplicate"
    }));
    assert_eq!(duplicate.status().as_u16(), 200);
    let duplicate_register = client()
        .post(format!("{}/v1/workers/register", gateway.base))
        .bearer_auth("duplicate-control-token")
        .json(&json!({
            "endpoint": endpoint,
            "incarnation": worker.incarnation,
            "capacity": {"active": 0, "limit": 4, "queued": 0, "queue_limit": 8}
        }))
        .send()
        .expect("registration responds");
    assert_eq!(duplicate_register.status().as_u16(), 409);
    assert_eq!(
        text(duplicate_register)["code"],
        "worker.duplicate_identity"
    );

    let old_incarnation = worker.incarnation.clone();
    gateway.restart();
    let reloaded = gateway.wait_worker("worker-live", |worker| worker["reachable"] == true);
    assert_eq!(reloaded["control_token_set"], true);
    assert!(gateway.registry.exists(), "registry state is durable");

    worker.restart();
    let reconciled = gateway.wait_worker("worker-live", |worker| {
        worker["reachable"] == true
            && worker["incarnations"].as_array().is_some_and(|entries| {
                entries.iter().any(|entry| {
                    entry["incarnation"] == old_incarnation && entry["superseded_at"].is_number()
                })
            })
    });
    assert_eq!(reconciled["instance"], worker.instance);
    assert_ne!(reconciled["incarnation"], old_incarnation);

    let after_restart = gateway.wait_task(&task_id);
    assert_eq!(after_restart["task"]["state"], "succeeded");
    assert_eq!(after_restart["task"]["output"], output);

    let removed = gateway.remove("worker-live");
    assert_eq!(removed.status().as_u16(), 200);
    assert_eq!(text(removed)["status"], "decommissioned");
    assert!(!ids(&gateway.discover(CALLER_TOKEN)).contains(&"worker-live".to_string()));
    assert!(gateway
        .request(reqwest::Method::GET, "/v1/admin/workers", ADMIN_TOKEN)
        .send()
        .expect("admin list responds")
        .json::<Vec<Value>>()
        .expect("admin list is JSON")
        .iter()
        .any(|worker| worker["id"] == "worker-live" && worker["status"] == "decommissioned"));
    let after_remove = gateway.wait_task(&task_id);
    assert_eq!(after_remove["task"]["state"], "succeeded");
    assert_eq!(after_remove["task"]["output"], output);

    let denied = gateway
        .request(reqwest::Method::GET, "/v1/admin/workers", CALLER_TOKEN)
        .send()
        .expect("unauthorized admin list responds");
    assert_eq!(denied.status().as_u16(), 403);
    let body = denied.text().expect("error body");
    assert!(!body.contains(&token));
    let denied_audit = gateway
        .request(
            reqwest::Method::GET,
            "/v1/admin/workers/audit",
            CALLER_TOKEN,
        )
        .send()
        .expect("unauthorized audit responds");
    assert_eq!(denied_audit.status().as_u16(), 403);
    assert!(!denied_audit.text().expect("error body").contains(&token));

    let audit = gateway.audit(ADMIN_TOKEN);
    let audit_text = serde_json::to_string(&audit).expect("audit JSON");
    assert!(
        !audit_text.contains(&token),
        "audit never exposes control tokens"
    );
    for action in [
        "worker.add",
        "worker.disable",
        "worker.enable",
        "worker.update",
        "worker.probe",
        "worker.decommission",
    ] {
        assert!(
            audit.iter().any(|entry| entry["action"] == action),
            "audit contains {action}: {audit_text}"
        );
    }

    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        let mode = std::fs::metadata(&gateway.registry)
            .expect("registry metadata")
            .permissions()
            .mode()
            & 0o777;
        assert_eq!(mode, 0o600, "registry file is private");
    }
}

#[test]
fn cli_and_sdk_admin_journeys_use_the_same_gateway_api() {
    let gateway = Gateway::start();

    let listed = Command::new(binary("gb-client"))
        .args([
            "--gateway",
            &gateway.base,
            "--token",
            ADMIN_TOKEN,
            "worker",
            "list",
            "--json",
        ])
        .output()
        .expect("cli runs");
    assert!(
        listed.status.success(),
        "{}",
        String::from_utf8_lossy(&listed.stderr)
    );
    assert_eq!(
        serde_json::from_slice::<Value>(&listed.stdout).expect("cli list JSON"),
        json!([])
    );

    let added = Command::new(binary("gb-client"))
        .args([
            "--gateway",
            &gateway.base,
            "--token",
            ADMIN_TOKEN,
            "worker",
            "add",
            "cli-worker",
            "http://127.0.0.1:1",
            "--no-preflight",
            "--json",
        ])
        .output()
        .expect("cli add runs");
    assert!(
        added.status.success(),
        "{}",
        String::from_utf8_lossy(&added.stderr)
    );
    let added: Value = serde_json::from_slice(&added.stdout).expect("cli add JSON");
    let token = added["control_token"]
        .as_str()
        .expect("generated token")
        .to_string();
    assert!(token.starts_with("gwb_"));
    assert_eq!(added["worker"]["status"], "approved");

    let shown = Command::new(binary("gb-client"))
        .args([
            "--gateway",
            &gateway.base,
            "--token",
            ADMIN_TOKEN,
            "worker",
            "show",
            "cli-worker",
            "--json",
        ])
        .output()
        .expect("cli show runs");
    assert!(shown.status.success());
    let shown: Value = serde_json::from_slice(&shown.stdout).expect("cli show JSON");
    assert_eq!(shown["control_token_set"], true);
    assert!(!shown.to_string().contains(&token));

    let inventory = Command::new(binary("gb-client"))
        .args([
            "--gateway",
            &gateway.base,
            "--token",
            ADMIN_TOKEN,
            "worker",
            "list",
            "--json",
        ])
        .output()
        .expect("cli inventory runs");
    assert!(inventory.status.success());
    assert!(!String::from_utf8_lossy(&inventory.stdout).contains(&token));

    let updated = Command::new(binary("gb-client"))
        .args([
            "--gateway",
            &gateway.base,
            "--token",
            ADMIN_TOKEN,
            "worker",
            "update",
            "cli-worker",
            "--revision",
            &shown["revision"].as_u64().expect("revision").to_string(),
            "--package",
            "general",
            "--json",
        ])
        .output()
        .expect("cli update runs");
    assert!(
        updated.status.success(),
        "{}",
        String::from_utf8_lossy(&updated.stderr)
    );

    for action in ["disable", "enable"] {
        let output = Command::new(binary("gb-client"))
            .args([
                "--gateway",
                &gateway.base,
                "--token",
                ADMIN_TOKEN,
                "worker",
                action,
                "cli-worker",
            ])
            .output()
            .expect("cli action runs");
        assert!(
            output.status.success(),
            "{}",
            String::from_utf8_lossy(&output.stderr)
        );
        assert!(!String::from_utf8_lossy(&output.stdout).contains(&token));
    }

    let audit = Command::new(binary("gb-client"))
        .args([
            "--gateway",
            &gateway.base,
            "--token",
            ADMIN_TOKEN,
            "worker",
            "audit",
            "--worker",
            "cli-worker",
            "--json",
        ])
        .output()
        .expect("cli audit runs");
    assert!(audit.status.success());
    let audit: Value = serde_json::from_slice(&audit.stdout).expect("cli audit JSON");
    assert!(!audit.to_string().contains(&token));
    assert!(audit.as_array().is_some_and(|entries| !entries.is_empty()));

    let removed = Command::new(binary("gb-client"))
        .args([
            "--gateway",
            &gateway.base,
            "--token",
            ADMIN_TOKEN,
            "worker",
            "remove",
            "cli-worker",
            "--json",
        ])
        .output()
        .expect("cli remove runs");
    assert!(removed.status.success());
    assert_eq!(
        serde_json::from_slice::<Value>(&removed.stdout).expect("cli remove JSON")["status"],
        "decommissioned"
    );

    let runtime = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        .build()
        .expect("runtime");
    let outcome = runtime.block_on(async {
        use common::{AddWorkerRequest, UpdateWorkerRequest};
        let client = sdk::Client::new(&gateway.base, ADMIN_TOKEN);
        let added = client
            .add_worker(&AddWorkerRequest {
                id: "sdk-worker".into(),
                endpoint: "http://127.0.0.1:1".into(),
                instance: None,
                package: None,
                capabilities: Some(vec!["general".into()]),
                control_token: None,
                preflight: false,
                idempotency_key: "sdk-add".into(),
            })
            .await
            .expect("sdk add");
        let token = added.control_token.expect("one-time token");
        let revision = added.worker.revision;
        let updated = client
            .update_worker(
                "sdk-worker",
                &UpdateWorkerRequest {
                    revision,
                    endpoint: None,
                    instance: None,
                    package: Some("general".into()),
                    capabilities: None,
                    idempotency_key: Some("sdk-update".into()),
                },
            )
            .await
            .expect("sdk update");
        assert_eq!(updated.revision, revision + 1);
        assert_eq!(
            client
                .disable_worker("sdk-worker")
                .await
                .expect("sdk disable")
                .status,
            "disabled"
        );
        assert_eq!(
            client
                .enable_worker("sdk-worker")
                .await
                .expect("sdk enable")
                .status,
            "approved"
        );
        let workers = client.admin_workers().await.expect("sdk inventory");
        assert!(workers.iter().any(|worker| worker.id == "sdk-worker"));
        let audit = client
            .worker_audit(Some("sdk-worker"))
            .await
            .expect("sdk audit");
        assert!(!serde_json::to_string(&audit).unwrap().contains(&token));
        assert_eq!(
            client
                .decommission_worker("sdk-worker")
                .await
                .expect("sdk remove")
                .status,
            "decommissioned"
        );
        client.admin_worker("sdk-worker").await.expect("sdk show")
    });
    assert_eq!(outcome.status, "decommissioned");
}
